/**
 * Dispatch bridge checks: lifecycle, idempotency, relay, revisions, watchdog, auth.
 * Run: node prototypes/studio-mock/api/lib/dispatch.test.js
 */
import { generateKeyPairSync, sign } from "node:crypto";
import { createDispatchStore, createMemoryStorage, LIMITS } from "./dispatch-store.js";
import { createDispatchService } from "./dispatch-service.js";
import { verifyJwt, authorizeDispatchCaller, authorizeRelay, _resetJwksCache, MCP_AUDIENCE, RELAY_AUDIENCE } from "./dispatch-auth.js";

function assert(cond, msg) {
  if (!cond) throw new Error(msg);
}

let clock = Date.parse("2026-10-22T21:00:00Z");
const now = () => clock;
const fires = [];
let fireOk = true;
const fire = async (text) => {
  fires.push(JSON.parse(text));
  return fireOk ? { ok: true, sessionId: `session_${fires.length}`, sessionUrl: `https://claude.ai/code/session_${fires.length}` } : { ok: false, error: "fire_503: overloaded" };
};
const store = createDispatchStore(createMemoryStorage());
const svc = createDispatchService({ store, fire, now });

function comment(id, kind, extra = {}, n = Math.random()) {
  const marker = JSON.stringify({ id, kind, rev: extra.rev ?? 0, session: "session_x", ...extra.marker });
  return {
    kind: "comment",
    id: String(extra.cid || n),
    url: "https://github.com/evanrobinson2/abbiesworld_ios/issues/90#c",
    issueNumber: 90,
    issueUrl: "https://github.com/evanrobinson2/abbiesworld_ios/issues/90",
    body: `<!-- abbies-dispatch:v1 ${marker} -->\n${extra.text || kind}\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_`,
    verification: extra.verification || null,
  };
}

// 1. build stores, fires, and reports "submitted" with a fired delivery.
const b = await svc.build({ request: "Build a Roman watchtower", requester: { sub: "auth0|evan" } });
assert(b.status === "submitted" && b.delivery.state === "fired", "build fired");
assert(/^D-\d{6}-[A-Z2-9]{5}$/.test(b.dispatch_id), "id shape");
assert(fires.length === 1 && fires[0].request === "Build a Roman watchtower" && fires[0].reason === "new", "fire payload");
const id = b.dispatch_id;

// 2. duplicate request inside the window returns the same dispatch, no second fire.
const dup = await svc.build({ request: "  build a ROMAN watchtower ", requester: {} });
assert(dup.duplicate && dup.dispatch_id === id && fires.length === 1, "idempotent build");

// 3. ack → acknowledged; replaying the same comment is a no-op.
const ack = comment(id, "ack", { cid: "c1", text: "Got it, starting." });
let r = await svc.relay(ack);
assert(r.applied, "ack applied");
r = await svc.relay(ack);
assert(r.duplicate, "replayed comment ignored");
let s = await svc.status({ dispatch_id: id });
assert(s.status === "acknowledged" && s.git.issue_url.endsWith("/90"), "acknowledged + issue linked");

// 4. progress → running; inbox returns ack+progress once, then nothing.
await svc.relay(comment(id, "progress", { cid: "c2", text: "Tower shell modeled." }));
let box = await svc.inbox({});
assert(box.messages.length === 2 && box.messages[1].kind === "progress", "inbox has 2");
box = await svc.inbox({});
assert(box.messages.length === 0, "inbox marked read");
box = await svc.inbox({ unread_only: false, acknowledge: false });
assert(box.messages.length === 2, "history readable");

// 5. revise while running queues; completion releases it as a new fire.
const rv = await svc.revise({ dispatch_id: id, instructions: "Make it taller", requester: {} });
assert(rv.pending_revision && fires.length === 1, "revision queued while running");
await svc.relay(comment(id, "completed", {
  cid: "c3",
  text: "Done. Tower in scene.",
  marker: { commits: ["abc1234"], prs: [91], branch: "claude/dispatch-x" },
  verification: { ok: true, detail: { commits: { abc1234: true } } },
}));
s = await svc.status({ dispatch_id: id });
assert(fires.length === 2 && fires[1].reason === "revision" && fires[1].revision === 1, "queued revision delivered on completion");
assert(s.status === "submitted" && s.revision === 1, "revision reopened dispatch");
// an old-revision completion must not complete the new revision
await svc.relay(comment(id, "completed", { cid: "c3b", rev: 0, text: "late duplicate" }));
s = await svc.status({ dispatch_id: id });
assert(s.status === "submitted", "old revision ignored for status");
await svc.relay(comment(id, "ack", { cid: "c4", rev: 1 }));
await svc.relay(comment(id, "completed", { cid: "c5", rev: 1, marker: { commits: ["def5678"] }, verification: { ok: true } }));
s = await svc.status({ dispatch_id: id });
assert(s.status === "completed" && s.verified && s.git.commits.includes("def5678") && s.git.prs[0].endsWith("/91"), "completed + verified");

// 6. unverified completion stays verified=false.
const b2 = await svc.build({ request: "Add soldiers" });
await svc.relay(comment(b2.dispatch_id, "ack", { cid: "d1" }));
await svc.relay(comment(b2.dispatch_id, "completed", { cid: "d2", marker: { commits: ["0000000"] }, verification: { ok: false, detail: "commit missing" } }));
s = await svc.status({ dispatch_id: b2.dispatch_id });
assert(s.status === "completed" && s.verified === false, "unverified completion flagged");

// 7. fire failure: stays submitted, retried with backoff, then fails after max attempts.
fireOk = false;
const b3 = await svc.build({ request: "Animate the guards" });
assert(b3.delivery.state === "pending" && b3.delivery.last_error, "fire failure recorded");
let before = fires.length;
await svc.sweep();
assert(fires.length === before + 1, "immediate first retry");
await svc.sweep();
assert(fires.length === before + 1, "backoff respected");
for (let i = 0; i < 10; i++) { clock += 31 * 60_000; await svc.sweep(); }
s = await svc.status({ dispatch_id: b3.dispatch_id });
assert(s.status === "failed" && s.delivery.attempts === LIMITS.maxDeliveryAttempts, `gives up after ${LIMITS.maxDeliveryAttempts}: ${s.status} ${s.delivery.attempts}`);
fireOk = true;
// revise revives a failed dispatch
await svc.revise({ dispatch_id: b3.dispatch_id, instructions: "try again" });
s = await svc.status({ dispatch_id: b3.dispatch_id });
assert(s.status === "submitted" && s.delivery.state === "fired", "revise after failure refires");

// 8. fired but never acknowledged → refired, then given up.
const b4 = await svc.build({ request: "Deploy the scene" });
const attempts = async (d) => (await store.get(d)).delivery.attempts;
clock += LIMITS.ackTimeoutMs + 1000; await svc.sweep();
assert((await attempts(b4.dispatch_id)) === 2, "unacked refire 1");
clock += LIMITS.ackTimeoutMs + 1000; await svc.sweep();
clock += LIMITS.ackTimeoutMs + 1000; await svc.sweep();
s = await svc.status({ dispatch_id: b4.dispatch_id });
assert(s.status === "failed" && /never acknowledged/.test(s.error) && s.delivery.attempts === 3, "unacked gives up");

// 9. interrupted execution: acked, then silent → resume fire once, then give up.
const b5 = await svc.build({ request: "Long build" });
await svc.relay(comment(b5.dispatch_id, "ack", { cid: "e1" }));
clock += LIMITS.staleRunMs + 1000; await svc.sweep();
let rec5 = await store.get(b5.dispatch_id);
assert(rec5.delivery.attempts === 2 && rec5.delivery.sessions[1].reason === "resume", "resume fired");
await svc.sweep();
assert((await attempts(b5.dispatch_id)) === 2, "resume not repeated immediately");
await svc.relay(comment(b5.dispatch_id, "progress", { cid: "e2", text: "resumed" }));
s = await svc.status({ dispatch_id: b5.dispatch_id });
assert(s.status === "running", "resumed session reports progress");
clock += LIMITS.staleRunMs + 1000; await svc.sweep();
s = await svc.status({ dispatch_id: b5.dispatch_id });
assert(s.status === "failed" && /quiet/.test(s.error), "second stall gives up");

// 10. question → blocked; revise answers and refires.
const b6 = await svc.build({ request: "Pick tower stone" });
await svc.relay(comment(b6.dispatch_id, "question", { cid: "f1", text: "Limestone or granite?" }));
s = await svc.status({ dispatch_id: b6.dispatch_id });
assert(s.status === "blocked" && /Limestone/.test(s.needs_input), "blocked with question");
await svc.revise({ dispatch_id: b6.dispatch_id, instructions: "Limestone" });
assert(fires[fires.length - 1].dispatch_id === b6.dispatch_id && fires[fires.length - 1].revisions[0].instructions === "Limestone", "answer delivered");

// 11. explicit idempotency key holds beyond the window.
const k1 = await svc.build({ request: "Thing A", idempotency_key: "voice-123" });
clock += 2 * 3600_000;
const k2 = await svc.build({ request: "Thing A", idempotency_key: "voice-123" });
assert(k2.duplicate && k2.dispatch_id === k1.dispatch_id, "explicit key dedupes");

// 12. status() with no id lists actives.
const all = await svc.status({});
assert(Array.isArray(all.active) && all.counts.completed >= 2, "status all");

// 13. concurrent relays on the same record all land (optimistic concurrency).
const b7 = await svc.build({ request: "Concurrency" });
await Promise.all([1, 2, 3, 4, 5].map((n) => svc.relay(comment(b7.dispatch_id, "progress", { cid: `p${n}`, text: `step ${n}` }))));
const rec7 = await store.get(b7.dispatch_id);
assert(rec7.messages.length === 5, `concurrent relays kept: ${rec7.messages.length}`);

// 14. factory feed: stages, partial progress, concept art and models, mid-run steering, phone alerts.
const alerts = [];
const svc2 = createDispatchService({ store, fire, now, notify: async (rec, msg) => { alerts.push({ id: rec.id, kind: msg.kind, checkpoint: msg.checkpoint }); return { sent: 1 }; } });
const f = await svc2.build({ request: "Roman watchtower with soldiers" });
const fid = f.dispatch_id;
await svc2.relay(comment(fid, "ack", { cid: "g1" }));
await svc2.relay(comment(fid, "progress", { cid: "g2", text: "Concept art ready", marker: {
  stage: "concept", checkpoint: "concept_art",
  images: [{ label: "front", url: "https://raw.githubusercontent.com/evanrobinson2/abbiesworld_ios/x/front.png" }, "http://insecure/x.png"],
  progress: { done: 1, total: 5, unit: "stages" },
} }));
let fd = await svc2.feed({});
let parcel = fd.parcels.find((p) => p.parcel_id === fid);
assert(parcel.stage === "concept" && parcel.artifacts.length === 1 && parcel.artifacts[0].type === "image", "concept art on parcel (https only)");
assert(parcel.progress.fraction === 0.2 && parcel.machine.state === "working", "partial progress + machine working");
assert(fd.machines.some((m) => m.parcel_id === fid), "machine listed");
assert(alerts.some((a) => a.id === fid && a.checkpoint === "concept_art"), "phone alert for concept art");
const ev = fd.events.filter((e) => e.dispatch_id === fid);
assert(ev.length === 2 && ev[1].images.length === 1 && ev[1].checkpoint === "concept_art", "feed events carry images");
// Evan steers mid-run from the app: queued, posted to the issue, then taken in by the running session.
await svc2.revise({ dispatch_id: fid, instructions: "Make the roof red", requester: { via: "app" } });
let posts = await svc2.pendingIssuePosts();
let mine = posts.filter((p) => p.dispatch_id === fid);
assert(mine.length === 1 && mine[0].issue === 90 && mine[0].revision === 1, "revision to post on issue");
await svc2.revisionPosted({ dispatch_id: fid, revision: 1, comment_url: "https://github.com/x#c" });
posts = await svc2.pendingIssuePosts();
assert(!posts.some((p) => p.dispatch_id === fid), "posted once");
await svc2.relay(comment(fid, "progress", { cid: "g3", rev: 1, text: "Red roof applied", marker: { stage: "model", models: [{ label: "tower", url: "https://example.com/tower.glb" }], progress: { done: 3, total: 5 } } }));
let rec = await store.get(fid);
assert(!rec.pendingRevision && rec.status === "running" && rec.stage === "model", "revision taken in mid-run");
fd = await svc2.feed({ dispatch_id: fid });
parcel = fd.parcels[0];
assert(parcel.artifacts.some((a) => a.type === "model") && parcel.stages.map((x) => x.name).join(",") === "concept,model", "models + stage history");
const since = fd.next_since;
assert((await svc2.feed({ since })).events.length === 0, "feed since cursor");

const act = await svc2.activity({});
const firstMine = act.events.find((e) => e.jobId === fid);
assert(firstMine && firstMine.stage === "model" && firstMine.model === "https://example.com/tower.glb" && firstMine.status === "running", "activity shape, newest first");
assert(act.events.some((e) => e.jobId === fid && e.image && e.checkpoint === "concept_art"), "concept art event in activity");

/* auth */
const { publicKey, privateKey } = generateKeyPairSync("rsa", { modulusLength: 2048 });
const jwk = { ...publicKey.export({ format: "jwk" }), kid: "k1", alg: "RS256", use: "sig" };
const fetchImpl = async () => ({ ok: true, json: async () => ({ keys: [jwk] }) });
function jwt(claims) {
  const enc = (o) => Buffer.from(JSON.stringify(o)).toString("base64url");
  const head = enc({ alg: "RS256", kid: "k1", typ: "JWT" });
  const body = enc(claims);
  const sig = sign("RSA-SHA256", Buffer.from(`${head}.${body}`), privateKey).toString("base64url");
  return `${head}.${body}.${sig}`;
}
const exp = Math.floor(Date.now() / 1000) + 600;
_resetJwksCache();
let a = await authorizeDispatchCaller(jwt({ iss: "https://dev-33h7qd4ytudlk0ls.us.auth0.com/", aud: [MCP_AUDIENCE], sub: "auth0|evan", exp }), { fetchImpl });
assert(a.ok && a.requester.sub === "auth0|evan", "auth0 token accepted");
a = await authorizeDispatchCaller(jwt({ iss: "https://evil.example/", aud: MCP_AUDIENCE, sub: "x", exp }), { fetchImpl });
assert(!a.ok && a.error === "issuer_rejected", "foreign issuer rejected");
a = await authorizeDispatchCaller(jwt({ iss: "https://dev-33h7qd4ytudlk0ls.us.auth0.com/", aud: "https://other", sub: "x", exp }), { fetchImpl });
assert(!a.ok, "wrong audience rejected");
a = await authorizeDispatchCaller(jwt({ iss: "https://dev-33h7qd4ytudlk0ls.us.auth0.com/", aud: MCP_AUDIENCE, sub: "x", exp: 100 }), { fetchImpl });
assert(!a.ok && a.error === "expired", "expired rejected");
const tampered = jwt({ iss: "https://dev-33h7qd4ytudlk0ls.us.auth0.com/", aud: MCP_AUDIENCE, sub: "x", exp }).split(".");
tampered[1] = Buffer.from(JSON.stringify({ iss: "https://dev-33h7qd4ytudlk0ls.us.auth0.com/", aud: MCP_AUDIENCE, sub: "admin", exp })).toString("base64url");
a = await authorizeDispatchCaller(tampered.join("."), { fetchImpl });
assert(!a.ok && a.error === "bad_signature", "tampered rejected");
const gh = (wf, ref = "refs/heads/main", aud = RELAY_AUDIENCE) => jwt({
  iss: "https://token.actions.githubusercontent.com", aud, exp, sub: "repo:evanrobinson2/abbiesworld_ios:ref:" + ref,
  repository: "evanrobinson2/abbiesworld_ios", ref, workflow_ref: `evanrobinson2/abbiesworld_ios/.github/workflows/${wf}@${ref}`,
});
assert((await authorizeRelay(gh("dispatch-relay.yml"), { fetchImpl })).ok, "relay workflow accepted");
assert(!(await authorizeRelay(gh("dispatch-relay.yml", "refs/pull/5/merge"), { fetchImpl })).ok, "PR-ref workflow rejected");
assert(!(await authorizeRelay(gh("other.yml"), { fetchImpl })).ok, "other workflow rejected");
assert((await authorizeDispatchCaller(gh("dispatch-e2e.yml", "refs/heads/main", MCP_AUDIENCE), { fetchImpl })).ok, "e2e workflow may call tools");
assert(!(await authorizeDispatchCaller(gh("dispatch-relay.yml", "refs/heads/main", MCP_AUDIENCE), { fetchImpl })).ok, "relay workflow may not call tools");
assert(!(await verifyJwt("abc", { issuers: [], audiences: [] })).ok, "garbage rejected");

console.log("dispatch.test.js OK", fires.length, "fires");
